SELECT U.HASHED_PASSWORD, 
  FROM USERS U
  LEFT JOIN DEPARTMENT DEPT ON U.DEPARTMENT_ID = DEPT.ID
 WHERE U.USERNAME = #{username}
   AND U.STATUS = #{status}
 ORDER BY U.FULL_NAME, U.ID

SELECT 
  FROM USERS U
  LEFT JOIN DEPARTMENT DEPT ON U.DEPARTMENT_ID = DEPT.ID
 WHERE U.STATUS = #{status}
   AND U.JOIN_STATUS = #{joinStatus}
 ORDER BY U.FULL_NAME, U.ID

SELECT COUNT(1) > 0
  FROM USERS
 WHERE EMAIL = #{email}
   AND STATUS = #{status}
